<?php
$submissionSearch = is_string($_GET['q'] ?? null) ? trim($_GET['q']) : '';
$submissionFilter = is_string($_GET['submission_status'] ?? null) ? $_GET['submission_status'] : '';
$submissionQuery = db()->prepare('SELECT * FROM activity_submissions WHERE classroom_id = ? AND item_id = ?'); $submissionQuery->execute([$classroomId, $itemId]);
$activityResponses = array_column($submissionQuery->fetchAll(), null, 'student_id');
$activityFiles = [];
foreach (submission_files(db(), $classroomId, $itemId) as $file) $activityFiles[(int) $file['student_id']][] = $file;
$submissionStudents = array_values(array_filter($students, function ($student) use ($submissionSearch, $submissionFilter, $activityResponses, $book, $itemId) {
    $sid = (int) $student['id']; $graded = isset($book['scores'][$itemId][(string) $sid]) || isset($book['overrides'][(string) $sid][$itemId]);
    $status = $graded ? 'graded' : (isset($activityResponses[$sid]) ? 'submitted' : 'missing');
    return ($submissionSearch === '' || str_contains(mb_strtolower($student['name']), mb_strtolower($submissionSearch))) && ($submissionFilter === '' || $submissionFilter === $status);
}));
$entryPage = page_records($submissionStudents, 'page', 20);
?>
<section class="glass panel academic-submission-grading"><div class="academic-panel-heading"><div><h2><?php echo esc($item['name']); ?></h2><p><?php echo esc(ucfirst($item['period_id'] ?? '') . ' | ' . (grading_category($book, $item['category_id'])['name'] ?? '') . ' | Maximum: ' . grade_display($item['max_score'])); ?></p></div><a class="button button-secondary" href="<?php echo esc($url . '&view=items&period=' . ($item['period_id'] ?? 'prelim') . '&item_id=' . rawurlencode($itemId)); ?>">Edit activity</a></div>
<?php if (!empty($item['instructions'])): ?><details><summary>Activity instructions</summary><p><?php echo nl2br(esc($item['instructions'])); ?></p></details><?php endif; ?>
<p><?php echo count($activityResponses); ?> / <?php echo count($students); ?> students submitted. Review each answer and download attached files, then enter the score and feedback in the same row.</p>
<form method="get" class="academic-filter-bar"><input type="hidden" name="classroom_id" value="<?php echo $classroomId; ?>"><input type="hidden" name="view" value="entry"><input type="hidden" name="item_id" value="<?php echo esc($itemId); ?>"><input type="hidden" name="period" value="<?php echo esc($item['period_id'] ?? 'prelim'); ?>"><label><span>Student</span><input type="search" name="q" value="<?php echo esc($submissionSearch); ?>"></label><label><span>Submission status</span><select name="submission_status"><?php foreach ([''=>'All students','submitted'=>'Submitted / needs grading','missing'=>'No submission','graded'=>'Graded'] as $key=>$label): ?><option value="<?php echo esc($key); ?>" <?php echo $submissionFilter === $key ? 'selected' : ''; ?>><?php echo esc($label); ?></option><?php endforeach; ?></select></label><button class="button button-secondary">Filter</button></form>
<?php if (!empty($book['locked'])): ?><p class="academic-notice">Grades are finalized. Reopen the release in Semester Summary to edit.</p><?php endif; ?>
<form method="post" class="stack-form" data-grade-dirty><?php render_grade_form_fields($book); ?><input type="hidden" name="action" value="scores"><input type="hidden" name="item_id" value="<?php echo esc($itemId); ?>">
<div class="academic-table-scroll"><table class="academic-table academic-submission-table"><thead><tr><th scope="col">Student / status</th><th scope="col">Answer and files</th><th scope="col">Score / <?php echo esc(grade_display($item['max_score'])); ?></th><th scope="col">Teacher feedback</th></tr></thead><tbody>
<?php foreach ($entryPage['items'] as $student): $sid = (int) $student['id']; $response = $activityResponses[$sid] ?? null; $savedScore = $book['scores'][$itemId][(string) $sid] ?? null; $postedScore = $error ? ($_POST['scores'][$sid] ?? null) : null; $adjusted = isset($book['overrides'][(string) $sid][$itemId]); ?>
<tr><th scope="row"><?php echo esc($student['name']); ?><small><?php echo $savedScore !== null || $adjusted ? 'Graded' : ($response ? 'Needs grading' : 'No submission'); ?></small><?php if ($response): ?><small>Submitted <?php echo esc(format_date($response['submitted_at'])); ?></small><?php if (!empty($item['due_at']) && strtotime($response['submitted_at']) > strtotime($item['due_at'])): ?><small>Late submission</small><?php endif; ?><?php endif; ?></th>
<td><?php if ($response): ?><?php if ($response['response'] !== ''): ?><div class="academic-response-text"><?php echo nl2br(esc($response['response'])); ?></div><?php endif; ?><?php render_submission_files($activityFiles[$sid] ?? []); ?><?php else: ?><span class="muted">Nothing submitted yet.</span><?php endif; ?></td>
<td><input aria-label="<?php echo esc($student['name'] . ' score'); ?>" name="scores[<?php echo $sid; ?>]" type="number" min="0" max="<?php echo esc((string) $item['max_score']); ?>" step="0.01" placeholder="Ungraded" value="<?php echo esc(is_string($postedScore) ? $postedScore : ($savedScore === null ? '' : (string) $savedScore)); ?>" <?php echo !empty($book['locked']) ? 'disabled' : ''; ?>><?php if (isset($book['component_scores'][$item['period_id'] ?? 'all'][$item['category_id']][(string) $sid])): ?><small>A manual component grade is active. Clear it in Term Grade Entry to use the activity calculation.</small><?php endif; ?><?php if ($adjusted): ?><small>Adjustment active; restore automatic grade in student details to use this saved score.</small><?php endif; ?></td>
<td><textarea aria-label="<?php echo esc($student['name'] . ' feedback'); ?>" name="feedback[<?php echo $sid; ?>]" maxlength="2000" rows="3" <?php echo !empty($book['locked']) ? 'readonly' : ''; ?>><?php echo esc($error && is_string($_POST['feedback'][$sid] ?? null) ? $_POST['feedback'][$sid] : ($book['feedback'][$itemId][(string) $sid] ?? '')); ?></textarea></td></tr>
<?php endforeach; ?><?php if (!$entryPage['items']): ?><tr><td colspan="4">No students match these filters.</td></tr><?php endif; ?></tbody></table></div>
<?php if (empty($book['locked']) && $entryPage['items']): ?><label><span>Correction reason (required when changing a saved score)</span><input name="reason" maxlength="500" value="<?php echo esc($error && is_string($_POST['reason'] ?? null) ? $_POST['reason'] : ''); ?>"></label><div class="academic-save-bar"><p>Save this page before switching filters or pages. Saved scores update the term draft; publish in Semester Summary to release grades and feedback to students.</p><button class="button button-primary">Save Scores</button></div><?php endif; ?></form><?php render_pagination($entryPage); ?></section>
